/**
 * Illustrations d'état vide Totoro, portées des drawables d'origine.
 */
public enum class TotoroIllustration {
	HISTORY,
	FAVOURITES,
	FEED,
	COMMON,
	LOCAL,
	;

	private fun build(onSurface: Color, primary: Color, background: Color): ImageVector = when (this) {
		HISTORY -> totoroHistory(onSurface, primary, background)
		FAVOURITES -> totoroFavourites(onSurface, primary, background)
		FEED -> totoroFeed(onSurface, primary, background)
		COMMON -> totoroCommon(onSurface, primary, background)
		LOCAL -> totoroLocal(onSurface, primary, background)
	}

	@Composable
	public fun vector(): ImageVector {
		val onSurface = MaterialTheme.colorScheme.onSurface
		val primary = MaterialTheme.colorScheme.primary
		val background = MaterialTheme.colorScheme.background
		return remember(onSurface, primary, background) { build(onSurface, primary, background) }
	}
}
